3	interface ActionRunInputSnapshot {
4	    actionLabel: string
5	    convertMessage: string | null
6	    forEachByAction: Readonly<Record<string, ActionForEachConfig>>
7	}
8	
9	type Listener = () => void
10	
11	const INITIAL_SNAPSHOT: ActionRunInputSnapshot = {
12	    actionLabel: '',
13	    convertMessage: null,
14	    forEachByAction: {},
15	}
16	
17	/** Owns editable run options without subscribing popup roots. */
18	export class ActionRunInputStore {
19	    private readonly listeners = new Set<Listener>()
20	    private snapshot = INITIAL_SNAPSHOT
21	
22	    readonly getSnapshot = () => this.snapshot
23	
24	    readonly subscribe = (listener: Listener) => {
25	        this.listeners.add(listener)
26	
27	        return () => this.listeners.delete(listener)
28	    }
29	
30	    setActionLabel(actionLabel: string) {
31	        this.publish({ ...this.snapshot, actionLabel, convertMessage: null })
32	    }
33	
34	    setConvertMessage(convertMessage: string | null) {
35	        this.publish({ ...this.snapshot, convertMessage })
36	    }
37	
38	    setForEach(actionId: string, forEach: ActionForEachConfig | null) {
39	        const forEachByAction = { ...this.snapshot.forEachByAction }
40	        if (forEach) forEachByAction[actionId] = forEach
41	        else delete forEachByAction[actionId]
42	        this.publish({ ...this.snapshot, forEachByAction })
43	    }
44	
45	    private publish(snapshot: ActionRunInputSnapshot) {
46	        this.snapshot = snapshot
47	        for (const listener of this.listeners) listener()
48	    }
49	}
